import {renderColours} from './colour-plates.js?v=r3';
import {renderEquipment} from './equipment.js?v=eq6';
import {renderBook} from './book.js?v=b9';
import {mountViewer,studiesFor} from './detail-viewer.js?v=plate2';
import {scaleBinarySTL} from './stl-export.js';
const main=document.querySelector('#main');
const first={id:'constitution',name:'Constitution',registry:'NCC-1700',role:'Heavy cruiser',page:75,plate:'01:04:10',length:288.6,width:127.1,height:72.6,nacelles:2,crew:430,status:'Plate-scored · unsliced',accuracy:{plan:0.958,side:0.962,front:0.894},drawingNote:'The plate’s side view is drawn about 3 % taller than its printed 72.6 m height; the model follows the drawing (75.5 m). Its front view sits 1–2 m off the side view; the model follows plan and side.',model:'assets/constitution.stl',description:'The original heavy cruiser: a broad primary hull, a suspended engineering hull and paired warp nacelles. The starting point for this collection.'};
let ships=[],queue=[],cleanup=()=>{},viewer=null,routeSerial=0,toastTimer;
const $=s=>document.querySelector(s);
const plate=s=>`assets/fleet/${s.id}-plate.webp`;
const plan=s=>`assets/fleet/${s.id}-plan.webp?v=2`;
const link=s=>`#/ship/${s.id}`;
const folio=(name,code='01:04')=>`<div class="folio"><span><a href="#/">COMMAND SECTION</a> / ${name}</span><span>TECHNICAL ORDER ${code}</span></div>`;
const note=()=>`<div class="archive-note"><span class="eyebrow">A living companion to the manual</span><p>Selected sheets from your copy, brought into three dimensions. Source dimensions are transcribed from the drawings; hidden surfaces and small details are interpretations. New entries can join the same collection as it grows.</p></div>`;
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
function saveQueue(){try{localStorage.setItem('starfleet-print-bench-v1',JSON.stringify(queue));}catch{toast('Browser storage unavailable. This bench will last for this visit.');}$('#queue-count').textContent=queue.length;}
function index(){
 main.innerHTML=folio('FLEET INDEX')+`<section class="cover"><div class="cover-copy"><div class="redbar"></div><span class="eyebrow">An interactive field edition</span><h1>STAR FLEET<br>TECHNICAL<br>MANUAL</h1><p class="intro">From the printed page<br>to a fleet you can explore.</p><a class="btn" href="${link(first)}">Open the Constitution <span>↗</span></a></div><a class="cover-art" href="${link(first)}" aria-label="Explore the Constitution"><img src="${plan(first)}" alt="Constitution-class plan view from the manual"><div class="caption"><span>CLASS I / HEAVY CRUISER</span><span>NCC-1700 · PLATE 01</span></div></a></section><section aria-labelledby="catalogue-title"><div class="index-head"><div><span class="eyebrow">01 / Starship recognition</span><h2 id="catalogue-title">Five forms. One fleet.</h2></div><label class="search">FIND <input id="search" type="search" placeholder="Class, role or registry" autocomplete="off"></label></div><div class="catalogue" id="catalogue"></div><p id="no-results" hidden>No matching vessel. Try a class name or registry.</p></section><a class="colour-index-link" href="#/colours"><span class="colour-chips"><i style="background:#ba641f"></i><i style="background:#354fa0"></i><i style="background:#c92329"></i></span><div><span class="eyebrow">02 / Heraldry & dress</span><h2>The manual, in colour.</h2><p>Flags, division insignia and uniforms, reconstructed from the SF colour specifications.</p></div><span>↗</span></a><a class="colour-index-link eq-index-link" href="#/equipment"><span class="colour-chips"><i style="background:#202321"></i><i style="background:#9faaa9"></i><i style="background:#a72c25"></i></span><div><span class="eyebrow">03 / Standard field equipment</span><h2>The equipment locker.</h2><p>Phasers, communicators, tricorders and medical instruments, rebuilt in 3D from their technical orders.</p></div><span>↗</span></a><a class="colour-index-link book-index-link" href="#/book"><span class="colour-chips"><i style="background:#0b0b0c"></i><i style="background:#c8261f"></i><i style="background:#c9a34e"></i></span><div><span class="eyebrow">04 / The manual itself</span><h2>The 1975 book.</h2><p>The black binder and red manual as a book you can open, page through and zoom into, with the story of how Franz Joseph made it.</p></div><span>↗</span></a>`+note();
 function rows(q=''){const found=ships.filter(s=>`${s.name} ${s.registry} ${s.role}`.toLowerCase().includes(q.toLowerCase()));$('#catalogue').innerHTML=found.map(s=>`<a class="catalogue-row" href="${link(s)}"><span class="number">0${ships.indexOf(s)+1}</span><img src="${plan(s)}" alt="${s.name} plan view" loading="lazy"><div><h3>${s.name}</h3><p>${s.role.toUpperCase()} / ${s.registry}</p></div><span class="measure">${s.length} <small>m</small></span><span class="tag">DETAILED 3D<br>SOURCE PLATES · STL</span><span class="arrow">↗</span></a>`).join('');$('#no-results').hidden=!!found.length;}
 rows();$('#search').addEventListener('input',e=>rows(e.target.value));
}
function detail(s,serial){
 const idx=ships.indexOf(s);
 main.innerHTML=folio(s.name.toUpperCase(),s.plate)+`<div class="sheet-title"><div><span class="eyebrow">Class I / ${s.role}</span><h1>${s.name}</h1><p class="subtitle">${s.registry} · STARSHIP TECHNICAL STUDY</p></div><div class="sheet-code">SOURCE: PDF PAGE ${s.page}<br><b>INTERACTIVE PLATE 0${idx+1}</b></div></div><div class="sheet"><section class="drawing" aria-label="${s.name} interactive study"><div class="drawing-bar"><div class="tabs" role="tablist" aria-label="Study mode"><button role="tab" id="model-tab" class="active" aria-selected="true" aria-controls="model-panel">3D study</button><button role="tab" id="plate-tab" aria-selected="false" aria-controls="plate-panel">Technical plate</button></div><span class="paper-code">TO:${s.plate}</span></div><div class="study-selector"><label for="study-select">EXPLORE</label><select id="study-select">${studiesFor(s).map(x=>`<option value="${x.id}">${x.title}</option>`).join('')}</select><a id="visual-download" download href="assets/detail/${s.id}.glb">3D file ↓</a></div><div id="model-panel" role="tabpanel" aria-labelledby="model-tab"><div id="scene" tabindex="0" role="img" aria-label="${s.name} model. Drag to orbit. Arrow keys rotate; plus and minus zoom."><span class="scene-caption" id="view-name">PERSPECTIVE / RECONSTRUCTION</span><span class="loading" role="status">Preparing the study…</span></div><div class="drawing-controls"><div class="view-buttons" aria-label="Camera view">${['3D','Top','Side','Front'].map((v,i)=>`<button data-view="${v}" class="${i?'':'active'}" aria-pressed="${!i}">${v}</button>`).join('')}</div><div class="tools"><button class="icon-btn" id="turn" aria-pressed="false" aria-label="Toggle turntable">↻ Orbit</button><button class="icon-btn" id="zoom-in" aria-label="Zoom in">+</button><button class="icon-btn" id="zoom-out" aria-label="Zoom out">−</button><button class="icon-btn" id="reset">Fit model</button><button class="icon-btn" id="fullscreen" aria-label="Toggle fullscreen">⛶</button></div></div><p class="drawing-hint">DRAG TO ORBIT · SCROLL TO ZOOM · RIGHT-DRAG TO PAN</p></div><div id="plate-panel" role="tabpanel" aria-labelledby="plate-tab" hidden><div class="plate-tools"><button class="icon-btn" id="plate-zoom" aria-pressed="false">Enlarge drawing</button><label class="source-selector">SOURCE <select id="source-select" aria-label="Source sheet"></select></label><a id="source-open" href="${plate(s)}" target="_blank" rel="noopener">Open source sheet ↗</a>${s.id==='constitution'?'<a href="assets/blueprint-full.png" download="constitution-sharpened-blueprint.png">Sharpened original ↓</a>':''}</div><div class="plate-view"><img src="${plate(s)}" alt="Manual PDF page ${s.page}: ${s.name} top, side and front elevations with printed dimensions"></div></div><div class="study-notes" aria-live="polite"><strong id="study-heading">Complete starship</strong><p id="study-description"></p><p class="small" id="study-source"></p></div></section><aside class="particulars"><h2>PARTICULARS</h2><p class="description">${s.description}</p><dl><div><dt>Length overall</dt><dd>${s.length} m</dd></div><div><dt>Breadth</dt><dd>${s.width} m</dd></div><div><dt>Height</dt><dd>${s.height} m</dd></div><div><dt>Warp units</dt><dd>${s.nacelles}</dd></div><div><dt>Complement</dt><dd>${s.crew}</dd></div></dl><span class="eyebrow">Drawing finish</span><div class="finishes">${['Ivory','Blueprint','Mesh'].map((f,i)=>`<button data-finish="${f}" class="${i?'':'active'}" aria-pressed="${!i}">${f}</button>`).join('')}</div><label class="scale-control" for="size">MODEL LENGTH <output id="size-out">100 mm</output></label><input id="size" type="range" min="100" max="200" step="10" value="100"><div class="scale-summary" id="size-summary"></div><button class="btn" id="download">Download STL <span>↓</span></button><button class="btn outline" id="add">Add to print bench <span>+</span></button><p class="small" id="model-status">The STL is made from this same plate-measured hull as one closed piece: lettering, windows and deck lines are left off, thin plates are thickened to stay printable, the pylons are thickened to 2 mm at 100 mm, and feed horns too fine to print are omitted. It is geometry-checked, not test-printed. The detailed display models and cutaways are GLB files above the viewer.</p></aside></div><div class="spec-strip"><div><strong>01 / THE SOURCE</strong><p>Hull: PDF ${s.page}, TO ${s.plate}. Detailed systems: PDF 143–144.${s.id==='constitution'?' Bridge: 94–95. MK-IX hangar: 149–150.':''} Each study links to its source sheets.</p></div><div><strong>02 / THE INTERPRETATION</strong><p>Exterior detailing follows the later component drawings. Geometry hidden by the drawings, small controls, surface colours and door poses are interpretations.</p></div><div><strong>03 / THE PHYSICAL MODEL</strong><p>Choose a 100–200 mm length. Export units are millimetres. Prepare supports in your slicer before printing in PLA.</p></div></div><div class="pagination"><a href="${link(ships[(idx+ships.length-1)%ships.length])}">← ${ships[(idx+ships.length-1)%ships.length].name}</a><a href="#/compare">Compare the fleet</a><a href="${link(ships[(idx+1)%ships.length])}">${ships[(idx+1)%ships.length].name} →</a></div>`;
 $('#fullscreen').hidden=!document.fullscreenEnabled;$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.drawing').requestFullscreen();}catch{toast('Fullscreen is unavailable on this device.');}};
 const slider=$('#size');function sizeChange(){const n=+slider.value;$('#size-out').textContent=`${n} mm`;$('#size-summary').textContent=`1:${Math.round(s.length*1000/n).toLocaleString()} · ${(s.width*n/s.length).toFixed(1)} × ${n} × ${(s.height*n/s.length).toFixed(1)} mm`;}
 sizeChange();slider.oninput=sizeChange;
 $('#download').onclick=e=>download(s,+slider.value,e.currentTarget);
 $('#add').onclick=()=>{const existing=queue.find(x=>x.id===s.id);if(existing)existing.length=+slider.value;else queue.push({id:s.id,length:+slider.value});saveQueue();toast(`${s.name} · ${slider.value} mm added to your print bench.`);};
 const switchTab=mode=>{const is3D=mode==='model';$('#model-panel').hidden=!is3D;$('#plate-panel').hidden=is3D;for(const t of ['model','plate']){const b=$(`#${t}-tab`);b.classList.toggle('active',t===mode);b.setAttribute('aria-selected',String(t===mode));}viewer?.resize();};
 $('#model-tab').onclick=()=>switchTab('model');$('#plate-tab').onclick=()=>switchTab('plate');
 for(const t of ['model','plate'])$(`#${t}-tab`).onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const next=t==='model'?'plate':'model';switchTab(next);$(`#${next}-tab`).focus();}};
 $('#plate-zoom').onclick=e=>{const on=$('.plate-view').classList.toggle('zoomed');e.currentTarget.setAttribute('aria-pressed',String(on));e.currentTarget.textContent=on?'Fit drawing':'Enlarge drawing';};
 startViewer(s,serial);
}
function startViewer(s,serial){
 const studies=studiesFor(s);
 function updateStudy(study){
  $('#study-heading').textContent=study.title;
  $('#study-description').textContent=study.description;
  $('#study-source').textContent=study.note;
  $('#visual-download').href=study.file;$('#visual-download').download=`${s.id}-${study.id}-detailed.glb`;
  $('#visual-download').setAttribute('aria-label',`Download ${study.title} as GLB`);
  $('#scene').setAttribute('aria-label',`${study.title}. Drag to orbit. Arrow keys rotate; plus and minus zoom.`);
  const source=$('#source-select');source.innerHTML=study.pages.map((p,i)=>`<option value="${i}">PDF ${p}</option>`).join('');
  function showSheet(){const i=+source.value,p=study.pages[i],url=study.sources?.[i]||`assets/detail/page-${p}.webp`;const img=$('.plate-view img');img.src=url;img.alt=`Manual PDF page ${p}: source drawing for ${study.title}`;$('#source-open').href=url;}
  source.onchange=showSheet;showSheet();
 }
 viewer=mountViewer($('#scene'),s,updateStudy);
 cleanup=()=>{viewer?.dispose();viewer=null;};
}
async function download(s,length,button){
 const text=button.textContent;button.disabled=true;button.textContent='Preparing STL…';
 try{const r=await fetch(`assets/fleet/${s.id}-100mm.stl`);if(!r.ok)throw Error('Model download failed');const data=scaleBinarySTL(await r.arrayBuffer(),length);const url=URL.createObjectURL(new Blob([data],{type:'model/stl'}));const a=document.createElement('a');a.href=url;a.download=`${s.id}-${length}mm.stl`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast(`${s.name} STL exported at ${length} mm. Review supports in your slicer.`);}catch(e){toast('Download failed. Please try again.');console.error(e);}finally{button.disabled=false;button.textContent=text;}
}
function silhouette(s){return `<img src="assets/fleet/${s.id}-silhouette.png?v=5" alt="${s.name} side projection from its 3D study">`;}
function comparison(){
 main.innerHTML=folio('FLEET COMPARISON')+`<span class="eyebrow">Recognition / comparative dimensions</span><h1>A question of scale.</h1><p class="intro">Five variations on a shared design language. Compare their full-size lengths or plan a collection at one consistent scale.</p><div class="compare-options">${ships.map(s=>`<label><input type="checkbox" data-compare="${s.id}" checked> ${s.name}</label>`).join('')}</div><div class="comparison" id="comparison"></div><p class="small">Side projections of the reconstructed models. All five use the same length scale; the source sheets remain the dimensional reference.</p><div class="table-scroll"><table class="compare-table"><thead><tr><th>CLASS</th><th>LENGTH</th><th>BEAM</th><th>HEIGHT</th><th>AT 1:2000</th></tr></thead><tbody id="compare-body"></tbody></table></div><button class="btn" id="fleet-scale" style="margin-top:24px">Add selected fleet at 1:2000 <span>+</span></button><div class="archive-note"><span class="eyebrow">Build a coherent collection</span><p>At 1:2000, Ptolemy measures 111 mm and Federation 160 mm. Individual downloads can also share a 100 mm display length, but that gives each vessel a different scale.</p></div>`;
 function update(){const selected=[...document.querySelectorAll('[data-compare]:checked')].map(x=>x.dataset.compare);const list=ships.filter(s=>selected.includes(s.id));$('#comparison').innerHTML=list.length?list.map(s=>`<div class="comparison-row"><a href="${link(s)}"><h3>${s.name}</h3><p>${s.registry}</p></a><div class="silhouette">${silhouette(s)}</div><strong>${s.length} m</strong></div>`).join('')+`<div class="ruler"><span>0</span><span>80</span><span>160</span><span>240</span><span>320 m</span></div>`:'Select a vessel above to compare.';$('#compare-body').innerHTML=list.map(s=>`<tr><td><a href="${link(s)}">${s.name} ↗</a></td><td>${s.length} m</td><td>${s.width} m</td><td>${s.height} m</td><td>${(s.length/2).toFixed(1)} mm</td></tr>`).join('');}
 document.querySelectorAll('[data-compare]').forEach(x=>x.onchange=update);update();$('#fleet-scale').onclick=()=>{const selected=[...document.querySelectorAll('[data-compare]:checked')].map(x=>x.dataset.compare);if(!selected.length){toast('Select at least one vessel.');return;}for(const s of ships.filter(x=>selected.includes(x.id))){const item=queue.find(x=>x.id===s.id);if(item)item.length=s.length/2;else queue.push({id:s.id,length:s.length/2});}saveQueue();toast('Selected fleet added at 1:2000 scale. Open Print bench to export.');};
}
function bench(){
 main.innerHTML=folio('PRINT BENCH')+`<span class="eyebrow">From drawing to object</span><h1>Your next fleet.</h1><p class="bench-note">Collect the studies you want to make, choose their lengths and export STL files for your Centauri Carbon 2. This bench is saved in this browser; it does not send jobs to the printer.</p><div id="bench-list"></div><div class="print-steps"><div><h3>01 / GEOMETRY</h3><p>All four new studies pass closed-mesh and connected-body checks. Their main supports are reinforced; small sensor details remain delicate.</p></div><div><h3>02 / SLICING</h3><p>Use your CC2 PLA profile. Inspect orientation, supports, first-layer contact and narrow connections in the toolpath preview. New vessels have not been sliced.</p></div><div><h3>03 / FIRST ARTICLE</h3><p>A completed physical print is the final test. Record fragile features and support-removal problems before committing to a larger collection.</p></div></div>`;
 if(!queue.length){$('#bench-list').innerHTML=`<div class="empty"><h2>A fleet begins with one ship.</h2><p>Add a vessel from its technical study to begin.</p><a class="btn" href="#/">Browse the fleet <span>↗</span></a></div>`;return;}
 $('#bench-list').innerHTML=queue.map(q=>{const s=ships.find(s=>s.id===q.id);const options=[...new Set([100,120,150,160,180,200,q.length])].sort((a,b)=>a-b);return `<article class="bench-row"><a href="${link(s)}"><img src="${plan(s)}" alt="${s.name} plan view"></a><div><h3><a href="${link(s)}">${s.name} ↗</a></h3><p>${s.status}</p><p>Completed physical print unverified.</p></div><label>MODEL LENGTH<select data-size="${s.id}" aria-label="${s.name} model length">${options.map(n=>`<option value="${n}" ${n===q.length?'selected':''}>${n} mm</option>`).join('')}</select></label><div class="bench-actions"><button class="btn" data-download="${s.id}">Download STL ↓</button><button class="remove" data-remove="${s.id}" aria-label="Remove ${s.name} from print bench">Remove</button></div></article>`;}).join('');
 document.querySelectorAll('[data-size]').forEach(el=>el.onchange=()=>{queue.find(x=>x.id===el.dataset.size).length=+el.value;saveQueue();});
 document.querySelectorAll('[data-download]').forEach(el=>el.onclick=()=>download(ships.find(x=>x.id===el.dataset.download),queue.find(x=>x.id===el.dataset.download).length,el));
 document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{queue=queue.filter(x=>x.id!==el.dataset.remove);saveQueue();bench();});
}
function route(){cleanup();cleanup=()=>{};const serial=++routeSerial;const path=location.hash.slice(1)||'/';let nav='index';if(path.startsWith('/colours')){cleanup=renderColours(main,path);nav='colours';}else if(path==='/equipment'||path.startsWith('/equipment/')){cleanup=renderEquipment(main,path);nav='equipment';}else if(path==='/book'||path.startsWith('/book/')){cleanup=renderBook(main,path);nav='book';}else if(path==='/compare'){comparison();nav='compare';}else if(path==='/bench'){bench();nav='bench';}else if(path.startsWith('/ship/')){const s=ships.find(s=>s.id===path.split('/')[2]);if(s)detail(s,serial);else{main.innerHTML=folio('ENTRY NOT FOUND')+'<h1>That sheet is not in this edition.</h1><a class="btn" href="#/">Return to the fleet index</a>';}}else index();document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(!path.startsWith('/equipment/'))document.title=path.startsWith('/book')?'The 1975 manual · Star Fleet Manual':path==='/equipment'?'Equipment locker · Star Fleet Manual':path.startsWith('/colours')?'Colour plates · Star Fleet Manual':path.startsWith('/ship/')?`${ships.find(s=>s.id===path.split('/')[2])?.name||'Archive'} · Star Fleet Manual`:'Star Fleet · Interactive Technical Manual';window.scrollTo(0,0);}
async function boot(){try{const r=await fetch('assets/fleet/ships.json?v=plate2');if(!r.ok)throw Error('Catalogue unavailable');ships=[first,...await r.json()];try{const saved=JSON.parse(localStorage.getItem('starfleet-print-bench-v1')||'[]');if(Array.isArray(saved))queue=saved.filter((x,i,a)=>ships.some(s=>s.id===x.id)&&Number.isFinite(x.length)&&x.length>=100&&x.length<=200&&a.findIndex(y=>y.id===x.id)===i);}catch{}$('#queue-count').textContent=queue.length;addEventListener('hashchange',route);route();}catch(e){console.error(e);main.innerHTML='<h1>The archive could not load.</h1><p>Please reload to try again.</p>';}}
boot();
